<?php /** 출퇴근 시스템: 퇴근 처리 */
use App\Core\Db; require_once __DIR__.'/common.php'; if($_SERVER['REQUEST_METHOD']!=='POST'||!csrf_check(isset($_POST['_csrf'])?$_POST['_csrf']:'')){flash_set('danger','잘못된 요청입니다.');header('Location: ?r=대시보드');exit;} $pdo=Db::pdo(); $eid=attendance_employee_id($pdo); $today=attendance_today(); try{$r=attendance_today_record($pdo,$eid); if(!$r||!$r['check_in']) throw new Exception('오늘 출근 기록이 없습니다.'); if(!attendance_record_datetime_matches_work_date($r)) throw new Exception('오늘 날짜에 잘못된 출퇴근 기록이 있습니다. 관리자에게 날짜 불일치 기록 복구를 요청해주세요.'); if($r['check_out']) throw new Exception('이미 퇴근 처리되었습니다.'); $now=attendance_now(); if(strtotime($now)<=strtotime($r['check_in'])) throw new Exception('퇴근시간이 출근시간보다 빠를 수 없습니다.'); $raw=attendance_minutes($r['check_in'],$now); $deduct=attendance_break_minutes($pdo); $work=attendance_work_minutes($raw,$deduct); /* 근무시간 2시간 공제 */ $u=$pdo->prepare("UPDATE cpms_attendance_records SET check_out=:co,status='퇴근완료',raw_minutes=:raw,work_minutes=:m,updated_at=:u WHERE id=:id");$u->execute(array(':co'=>$now,':raw'=>$raw,':m'=>$work,':u'=>$now,':id'=>$r['id'])); flash_set('success','퇴근 처리되었습니다.');}catch(Exception $e){flash_set('danger',$e->getMessage());} header('Location: ?r=대시보드');